// CreateTableWithDBType creates the Purch_Rcpt_Header table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *PurchRcptHeader) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, PurchRcptHeaderTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetPurchRcptHeaderPostgresTableSchema()
	} else {
		schema = GetPurchRcptHeaderTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Purch_Rcpt_Header table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *PurchRcptHeader) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, PurchRcptHeaderTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (no)`,
		fmt.Sprintf("%s$Purch_Rcpt_Header$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (buy_from_vendor_no)`,
		fmt.Sprintf("%s$Purch_Rcpt_Header$vendor", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index vendor: %w", err)
	}
	var keys []sift.Key
	for _, spec := range purchRcptHeaderSIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, PurchRcptHeaderTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, PurchRcptHeaderTableName, keys)
}

// purchRcptHeaderSIFTSpecs are the table's keys with sum_index_fields
func purchRcptHeaderSIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *PurchRcptHeader) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, PurchRcptHeaderTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range purchRcptHeaderSIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, PurchRcptHeaderTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: PurchRcptHeaderTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, PurchRcptHeaderTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

